use vstd::prelude::*;

verus! {

/// Spec: the returned vector is exactly the common prefix of `str1` and `str2`,
/// i.e., the longest `p` such that:
/// 1) `p` is a prefix of `str1` and `str2`
/// 2) either `p` reaches the end of one string, or the next characters differ.
fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> (out: Vec<char>)
    ensures
        // out is a prefix of str1
        out.len() <= str1.len(),
        forall|k: int| 0 <= k < out.len() ==> out[k] == str1[k],
        // out is a prefix of str2
        out.len() <= str2.len(),
        forall|k: int| 0 <= k < out.len() ==> out[k] == str2[k],
        // maximality: at the first position after out, either one string ends or they differ
        out.len() == vstd::cmp::min(str1.len(), str2.len())
            || str1[out.len()] != str2[out.len()],
{
    let mut i: usize = 0;
    let max = std::cmp::min(str1.len(), str2.len());

    while i < max && str1[i] == str2[i]
        invariant
            0 <= i <= max,
            max == vstd::cmp::min(str1.len(), str2.len()),
            // characters match for all positions < i
            forall|k: int| 0 <= k < i ==> str1[k] == str2[k],
        decreases
            max - i,
    {
        i += 1;
    }

    // Help the verifier connect the loop exit condition to the postcondition.
    assert(i <= max);
    assert(max == vstd::cmp::min(str1.len(), str2.len()));
    assert(
        i == max || str1[i] != str2[i]
    );

    str1[..i].to_vec()
}

} // verus!

